edits.newText:
test("default values", () => {
    const res = mri([], { default: { foo: "bar" } });
    expect(res).toEqual({ _: [], foo: "bar" });
  });

  test("boolean default does not leak into _ when flag is supplied", () => {
    const res = mri(["--foo"], { boolean: "foo", default: { foo: true } });
    expect(res).toEqual({ _: [], foo: true });
    expect(typeof res.foo).toBe("boolean");
  });

  test("boolean default with short flag does not leak into _", () => {
    const res = mri(["-t"], { boolean: "t", default: { t: true } });
    expect(res).toEqual({ _: [], t: true });
  });

