{
  "name": "mri",
  "version": "1.1.4",
  "description": "Quickly scan for CLI flags and arguments",
  "repository": "lukeed/mri",
  "main": "lib/index.js",
  "types": "index.d.ts",
  "license": "MIT",
  "files": [
    "lib",
    "index.d.ts"
  ],
  "author": {
    "name": "Luke Edwards",
    "email": "luke.edwards05@gmail.com",
    "url": "lukeed.com"
  },
  "engines": {
    "node": ">=4"
  },
  "scripts": {
    "test": "vitest run",
    "bench": "node bench"
  },
  "keywords": [
    "argv",
    "arguments",
    "cli",
    "minimist",
    "options",
    "optimist",
    "parser",
    "args"
  ],
  "devDependencies": {
    "@types/bun": "latest"
  }
}

type Dict<T> = Record<string, T>;
type Arrayable<T> = T | T[];
type Default = Dict<any>;

declare function mri<T=Default>(args?: string[], options?: mri.Options): mri.Argv<T>;

declare namespace mri {
	export interface Options {
		boolean?: Arrayable<string>;
		string?: Arrayable<string>;
		alias?: Dict<Arrayable<string>>;
		default?: Dict<any>;
		unknown?(flag: string): void;
	}

	export type Argv<T=Default> = T & {
		_: string[];
	}
}

export = mri;

function toArr(any) {
	return any == null ? [] : Array.isArray(any) ? any : [any];
}

function toVal(out, key, val, opts) {
	var x, old=out[key], nxt=(
		!!~opts.string.indexOf(key) ? (val == null || val === true ? '' : String(val))
		: !!~opts.boolean.indexOf(key) ? (val === 'false' ? false : val === 'true' || (out._.push((x = +val,x * 0 === 0) ? x : val),!!val))
		: typeof val === 'boolean' ? val
		: (x = +val,x * 0 === 0) ? x : val
	);
	out[key] = old == null ? nxt : (Array.isArray(old) ? old.concat(nxt) : [old, nxt]);
}

module.exports = function (args, opts) {
	args = args || [];
	opts = opts || {};

	var k, arr, arg, name, val, out={ _:[] };
	var i=0, j=0, idx=0, len=args.length;

	const alibi = opts.alias !== void 0;
	const strict = opts.unknown !== void 0;
	const defaults = opts.default !== void 0;

	opts.alias = opts.alias || {};
	opts.string = toArr(opts.string);
	opts.boolean = toArr(opts.boolean);

	if (alibi) {
		for (k in opts.alias) {
			arr = opts.alias[k] = toArr(opts.alias[k]);
			for (i=0; i < arr.length; i++) {
				(opts.alias[arr[i]] = arr.concat(k)).splice(i, 1);
			}
		}
	}

	opts.boolean.forEach(key => {
		opts.boolean = opts.boolean.concat(opts.alias[key] = opts.alias[key] || []);
	});

	opts.string.forEach(key => {
		opts.string = opts.string.concat(opts.alias[key] = opts.alias[key] || []);
	});

	if (defaults) {
		for (k in opts.default) {
			opts.alias[k] = opts.alias[k] || [];
			(opts[typeof opts.default[k]] || []).push(k);
		}
	}

	const keys = strict ? Object.keys(opts.alias) : [];

	for (i=0; i < len; i++) {
		arg = args[i];

		if (arg === '--') {
			out._ = out._.concat(args.slice(++i));
			break;
		}

		for (j=0; j < arg.length; j++) {
			if (arg.charCodeAt(j) !== 45) break; // "-"
		}

		if (j === 0) {
			out._.push(arg);
		} else if (arg.substring(j, j + 3) === 'no-') {
			name = arg.substring(j + 3);
			if (strict && !~keys.indexOf(name)) {
				return opts.unknown(arg);
			}
			out[name] = false;
		} else {
			for (idx=j+1; idx < arg.length; idx++) {
				if (arg.charCodeAt(idx) === 61) break; // "="
			}

			name = arg.substring(j, idx);
			val = arg.substring(++idx) || (i+1 === len || (''+args[i+1]).charCodeAt(0) === 45 || args[++i]);
			arr = (j === 2 ? [name] : name);

			for (idx=0; idx < arr.length; idx++) {
				name = arr[idx];
				if (strict && !~keys.indexOf(name)) return opts.unknown('-'.repeat(j) + name);
				toVal(out, name, (idx + 1 < arr.length) || val, opts);
			}
		}
	}

	if (defaults) {
		for (k in opts.default) {
			if (out[k] === void 0) {
				out[k] = opts.default[k];
			}
		}
	}

	if (alibi) {
		for (k in out) {
			arr = opts.alias[k] || [];
			while (arr.length > 0) {
				out[arr.shift()] = out[k];
			}
		}
	}

	return out;
}

import { describe, test, expect } from "vitest";
import mri from "../lib/index.js";

describe("mri regression", () => {
  test("parses basic flags", () => {
    expect(mri(["--foo", "bar"])).toEqual({ _: [], foo: "bar" });
    expect(mri(["--foo", "--bar"])).toEqual({ _: [], foo: true, bar: true });
  });

  test("handles short flags", () => {
    expect(mri(["-a", "-b", "val"])).toEqual({ _: [], a: true, b: "val" });
    expect(mri(["-ab", "val"])).toEqual({ _: [], a: true, b: "val" });
  });

  test("handles -- separator", () => {
    expect(mri(["--", "--not-a-flag"])).toEqual({ _: ["--not-a-flag"] });
  });

  test("coerces numbers by default", () => {
    expect(mri(["--count", "42"])).toEqual({ _: [], count: 42 });
    expect(typeof mri(["--count", "42"]).count).toBe("number");
  });

  test("string opts preserve string values", () => {
    expect(mri(["-s", "0001234"], { string: "s" }).s).toBe("0001234");
    expect(typeof mri(["-s", "0001234"], { string: "s" }).s).toBe("string");
  });

  test("boolean flag with no value", () => {
    const res = mri(["-t", "moo"], { boolean: "t" });
    expect(res).toEqual({ t: true, _: ["moo"] });
    expect(typeof res.t).toBe("boolean");
  });

  test("alias mirrors values", () => {
    const res = mri(["--foo", "bar"], { alias: { foo: "f" } });
    expect(res.foo).toBe("bar");
    expect(res.f).toBe("bar");
  });

  test("default values", () => {
    const res = mri([], { default: { foo: "bar" } });
    expect(res).toEqual({ _: [], foo: "bar" });
  });

  test("unknown handler strict", () => {
    const unknown = (flag: string) => {
      throw new Error(`unknown ${flag}`);
    };
    expect(() => mri(["--unknown", "val"], { unknown })).toThrow();
  });
});

Now I have enough understanding of the repository. Let me analyze the bug in detail.

Looking at `lib/index.js`, specifically the `toVal` function (line 2-8):

```js
function toVal(out, key, val, opts) {
	var x, old=out[key], nxt=(
		!!~opts.string.indexOf(key) ? (val == null || val === true ? '' : String(val))
		: !!~opts.boolean.indexOf(key) ? (val === 'false' ? false : val === 'true' || (out._.push((x = +val,x * 0 === 0) ? x : val),!!val))
		: typeof val === 'boolean' ? val
		: (x = +val,x * 0 === 0) ? x : val
);
	out[key] = old == null ? nxt : (Array.isArray(old) ? old.concat(nxt) : [old, nxt]);
}
```

**Bug analysis**: When `boolean: 'foo'` and `default: { foo: true }` and `--foo` is supplied:
- The `defaults` block adds 'foo' to `opts.boolean` (because `typeof true === 'boolean'`)
- The parser sets `val = true` (boolean) because `--foo` has no `=` value and we're at end-of-args (line: `val = arg.substring(++idx) || (i+1 === len || (''+args[i+1]).charCodeAt(0) === 45 || args[++i]);`)
- In `toVal`, since key is in `opts.boolean`: `val === 'true'` is false (val is boolean, not string 'true'), so we enter the push branch
- `out._.push((x = +val,x * 0 === 0) ? x : val)` → `+true` = `1`, `1*0===0` is true → `out._.push(1)` — **the numeric leak!**

Let me write a reproducer to confirm:

#!/usr/bin/env node
// V1 helper for file-based hypothesis/evidence tracking inside workspace.
// Usage:
//   node .v1/helpers.js add-hypothesis '{"description":"...","evidence":["file:line"],"confidence":0.8,"files":["src/foo.ts"]}'
//   node .v1/helpers.js select-hypothesis <id>
//   node .v1/helpers.js add-evidence '{"type":"file_inspection","description":"...","source":"src/foo.ts","result":"supports"}'
//   node .v1/helpers.js add-file-inspected src/foo.ts
//   node .v1/helpers.js add-command '{"command":"npm test","exitCode":0,"stdout":"..."}'
//   node .v1/helpers.js add-verification '{"method":"vitest","command":"vitest run","passed":true,"output":"..."}'
//   node .v1/helpers.js status
import { readFileSync, writeFileSync, existsSync, mkdirSync } from "node:fs";
import { join, dirname } from "node:path";
import { randomUUID } from "node:crypto";

const STATE_PATH = join(process.cwd(), ".v1/state.json");

function load() {
  if (!existsSync(STATE_PATH)) {
    console.error("No .v1/state.json found at", STATE_PATH);
    process.exit(1);
  }
  const raw = readFileSync(STATE_PATH, "utf-8");
  return JSON.parse(raw);
}
function save(s) {
  mkdirSync(dirname(STATE_PATH), { recursive: true });
  writeFileSync(STATE_PATH, JSON.stringify(s, null, 2), "utf-8");
}

const cmd = process.argv[2];
if (!cmd || cmd === "help" || cmd === "--help") {
  console.log("Usage: node .v1/helpers.js <add-hypothesis|select-hypothesis|add-evidence|add-file-inspected|add-command|add-verification|status>");
  process.exit(0);
}
if (cmd === "status") {
  const s = load();
  console.log(JSON.stringify(s, null, 2));
  process.exit(0);
}
if (cmd === "add-hypothesis") {
  const arg = process.argv[3];
  if (!arg) { console.error("need JSON arg"); process.exit(1); }
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { description: arg, evidence: [] }; }
  const s = load();
  const h = {
    id: payload.id ?? `hyp-${randomUUID().slice(0, 8)}`,
    description: payload.description ?? "hypothesis",
    evidence: payload.evidence ?? [],
    confidence: payload.confidence ?? 0.5,
    status: payload.status ?? "active",
    files: payload.files,
  };
  s.hypotheses = s.hypotheses ?? [];
  s.hypotheses.push(h);
  // also push evidence entry for diagnosis
  s.evidence = s.evidence ?? [];
  s.evidence.push({ id: `ev-${randomUUID().slice(0, 8)}`, type: "other", description: `Hypothesis: ${h.description}`, source: h.files?.[0], result: "neutral", timestamp: new Date().toISOString(), phase: s.phase });
  save(s);
  console.log(h.id);
  process.exit(0);
}
if (cmd === "select-hypothesis") {
  const id = process.argv[3];
  if (!id) { console.error("need id"); process.exit(1); }
  const s = load();
  let found = false;
  for (const hyp of s.hypotheses) {
    if (hyp.id === id) { hyp.status = "selected"; s.selectedHypothesis = id; found = true; }
    else if (hyp.status === "selected") hyp.status = "active";
  }
  if (!found) { console.error("hypothesis not found", id); process.exit(1); }
  save(s);
  console.log("selected", id);
  process.exit(0);
}
if (cmd === "add-evidence") {
  const arg = process.argv[3];
  let payload;
  try { payload = JSON.parse(arg); } catch { payload = { description: arg }; }

